**clamp.go**

```go
package lesson

func Clamp(value, minimum, maximum int) int {
	if value < minimum {
		return minimum
	}
	if value > maximum {
		return maximum
	}
	return value
}
```

**clamp_test.go**

```go
package lesson

import "testing"

func TestClamp(t *testing.T) {
	tests := []struct {
		name  string
		value int
		want  int
	}{
		{name: "below minimum", value: -2, want: 0},
		{name: "inside range", value: 6, want: 6},
		{name: "above maximum", value: 15, want: 10},
	}
	for _, test := range tests {
		got := Clamp(test.value, 0, 10)
		if got != test.want {
			t.Errorf("%s: got %d; want %d", test.name, got, test.want)
		}
	}
}
```

**Run it**

```bash
go test ./...
```

The table names three distinct regions. The loop contains no condition that duplicates the implementation's clamp decisions.

**mode.go**

```go
package lesson

import "fmt"

func ParseMode(value string) (string, error) {
	if value == "" {
		return "safe", nil
	}
	if value != "safe" && value != "fast" {
		return "", fmt.Errorf("unsupported mode %q", value)
	}
	return value, nil
}
```

**mode_test.go**

```go
package lesson

import "testing"

func TestParseMode(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		want    string
		wantErr bool
	}{
		{name: "explicit value", input: "fast", want: "fast"},
		{name: "empty uses default", want: "safe"},
		{name: "unsupported value", input: "turbo", wantErr: true},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			got, err := ParseMode(test.input)
			if (err != nil) != test.wantErr {
				t.Fatalf("error = %v; wantErr %v", err, test.wantErr)
			}
			if got != test.want {
				t.Errorf("mode = %q; want %q", got, test.want)
			}
		})
	}
}
```

**Run it**

```bash
go test -v ./...
go test -run '^TestParseMode$/^unsupported_value$' ./...
```

Spaces in subtest names are displayed as underscores. The exact run pattern selects one path component under the parent.

**square.go**

```go
package lesson

func Square(value int) int {
	return value * value
}
```

**square_test.go**

```go
package lesson

import "testing"

func TestSquare(t *testing.T) {
	tests := []struct {
		name        string
		value, want int
	}{
		{name: "zero", value: 0, want: 0},
		{name: "positive", value: 7, want: 49},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			if got := Square(test.value); got != test.want {
				t.Errorf("got %d; want %d", got, test.want)
			}
		})
	}
}
```

**Run it**

```bash
go test -race ./...
```

Each row contains immutable values and the function is pure. No map, slice, environment variable, or output buffer is shared.
